function saveRestaurant(id){
  const item=window.ReelRestaurants.find(restaurant=>restaurant.id===id);
  if(!item)return false;
  const library=libraryIds();
  const locale=signupLocales.indexOf(signupLanguage());
  if(!place(id))state.places.push({id,restaurant:true,name:item.name[locale],ko:item.name[0],address:item.address,area:item.area[locale],type:'Food',duration:45,verified:true,recommended:true});
  if(!library.includes(id))library.push(id);
  save();
  return true;
}
