let guidesTab='discover';
function guideRequests(){const r=state.request,list=proposals(),open=r&&['requested','quoted'].includes(r.status)&&!state.booking;return `<div class="proposal-inbox"><div class="inbox-heading"><h2>Received proposals</h2><a href="#support">Service information</a></div><section class="request-group"><h3>Receiving proposals</h3>${open?requestInboxCard(r,list,true):`<button type="button" class="inbox-start" data-action="guides-tab" data-id="discover"><span class="inbox-start-icon">${icon('board')}</span><span><strong>Find your travel mate</strong><small>Get proposals tailored to your trip.</small></span><b aria-hidden="true">›</b></button>`}</section>${r&&!open?`<section class="request-group"><h3>Closed requests</h3><p class="request-group-note">This trip is no longer receiving proposals.</p>${requestInboxCard(r,list,false)}</section>`:''}</div>`;}
function requestInboxCard(r,list,open){const unread=list.filter(q=>!(state.viewedProposals||[]).includes(q.id+':'+q.version));const created=r.createdAt?new Date(r.createdAt).toLocaleDateString(document.documentElement.lang==='en'?'en-US':'ko-KR',{timeZone:'Asia/Seoul',month:'short',day:'numeric'}):'';return `<a href="#requested" class="request-inbox-card"><div class="request-inbox-meta"><span class="request-inbox-status ${open?'is-open':''}">${open?'Receiving proposals':state.booking?'Mate selected':'Close request'}</span><span>${esc(created)}</span></div><div class="request-inbox-title"><h4>${esc(r.tripTitle||state.title)}</h4><span>Proposals ${list.length} <b aria-hidden="true">›</b></span></div><p class="request-inbox-facts">${esc(r.date)} · ${r.party} ${r.party===1?"guest":"guests"} · ${(r.stops||[]).length} places</p><div class="request-inbox-footer">${list.length?`<span class="proposal-avatar-stack" aria-hidden="true">${list.slice(0,3).map(q=>`<span>${esc(q.guide[0])}</span>`).join('')}</span><span>${unread.length?'New proposals '+unread.length:'Compare received proposals'}</span>`:'<span>Mates are reviewing your trip</span>'}</div></a>`;}


const nicknameDirectoryKey='reeltrip-prototype-nicknames-v1',nicknameOwner='traveler-demo';
let checkedNickname='';
const normalizeNickname=value=>String(value||'').normalize('NFKC').replace(/\s+/gu,'').toLowerCase();
function readNicknameDirectory(){const raw=JSON.parse(localStorage.getItem(nicknameDirectoryKey)||'{}');if(!raw||typeof raw!=='object'||Array.isArray(raw))throw new Error('Invalid nickname directory');return {...raw,[normalizeNickname('\uBBF8\uB098')]:'mate-mina',[normalizeNickname('\uC900')]:'mate-jun'};}
function nicknameProblem(value,directory){const display=String(value||'').normalize('NFKC').trim(),canonical=normalizeNickname(display);if(display.length<2||display.length>20||canonical.length<2)return 'Enter a nickname with 2–20 characters.';if(/[\p{Cc}\p{Cf}]/u.test(display))return 'This nickname contains unsupported characters.';if(['\uB9B4\uD2B8\uB9BD','reeltrip','\uC6B4\uC601\uD300','\uACE0\uAC1D\uC13C\uD130','\uAD00\uB9AC\uC790'].some(word=>canonical.includes(word)))return 'Names that could impersonate staff are not allowed.';const owner=directory[canonical];return owner&&owner!==nicknameOwner?'This nickname is taken. Try another name.':'';}
function checkNickname(){const input=document.querySelector('#profile-form [name="nickname"]'),message=$('#nickname-status');checkedNickname='';try{const problem=nicknameProblem(input.value,readNicknameDirectory());message.textContent=problem||'This nickname is available.';message.dataset.valid=String(!problem);if(!problem)checkedNickname=normalizeNickname(input.value);}catch{message.textContent='Could not check availability. Please try again.';message.dataset.valid='false';}}
let profileDraftPhoto='';
function profileAvatar(photo=state.profile?.photo){return photo?`<img src="${esc(photo)}" alt="Profile photo">`:icon('account');}
function editProfile(){checkedNickname='';profileDraftPhoto=state.profile?.photo||'';modal(`<form id="profile-form"><div class="profile-dialog-heading"><h2>Edit profile</h2><button type="button" class="textbtn" data-action="close" aria-label="Close">×</button></div><div class="profile-photo-editor"><div class="profile-photo-preview" id="profile-photo-preview">${profileAvatar(profileDraftPhoto)}</div><label class="profile-camera-button" id="profile-camera-button" aria-label="Choose photo" ${profileDraftPhoto?'hidden':''}>${icon('camera')}<span class="sr-only">Choose photo</span><input id="profile-photo" type="file" accept="image/jpeg,image/png,image/webp"></label><button type="button" class="profile-photo-clear" id="profile-photo-clear" data-action="remove-profile-photo" aria-label="Remove photo" ${profileDraftPhoto?'':'hidden'}><span aria-hidden="true">×</span></button></div><p class="hint">JPG·PNG·WebP · Up to 1MB</p><label for="profile-nickname">Nickname</label><div class="nickname-entry"><input id="profile-nickname" name="nickname" required minlength="2" maxlength="20" value="${esc(state.profile?.nickname||'')}" placeholder="What should we call you?" autocomplete="nickname" aria-describedby="nickname-status"><button type="button" class="nickname-check" data-action="check-nickname">Check availability</button></div><p id="nickname-status" class="nickname-status" role="status" aria-live="polite"></p><p id="profile-error" class="error" role="alert"></p><button type="submit" id="profile-save" class="btn">Save</button></form>`);}
function account(){const mate=window.ReelAccess.mode()==='guide',booking=state.booking,request=state.request;const activeBooking=booking&&['awaiting_mate_fee','confirmed','cancellation_requested'].includes(booking.status),activeRequest=!activeBooking&&request&&['requested','quoted'].includes(request.status);return `<section class="my-page"><div class="my-heading"><h1>My account</h1><a class="my-settings-button" href="#settings" aria-label="Settings">${icon('settings')}</a></div><button type="button" class="my-profile" data-action="edit-profile" aria-label="Edit profile"><span class="my-avatar">${profileAvatar()}</span><span class="my-profile-copy"><strong>${esc(state.profile?.nickname||'Traveler')}</strong><small>${state.profile?.nickname?'Edit profile':'Add your nickname and photo'}</small></span><span class="profile-edit-chevron" aria-hidden="true">›</span></button>${activeBooking||activeRequest?`<section class="my-current"><span class="eyebrow">Your ongoing trip</span><h2>${esc(activeBooking?booking.date:request.tripTitle||state.title)}</h2><p>${esc(statusLabel(activeBooking?booking.status:request.status))}${activeRequest?' · '+proposals().length+'개의 Proposals':''}</p>${mate?btn('View request','guide-desk','secondary'):activeBooking?btn('View booking','booking','secondary'):'<a class="btn secondary" href="#guides" data-action="my-proposals">View received proposals</a>'}</section>`:''}<div class="my-menu">${mate?`<a href="#guide-calendar">Manage availability<span>›</span></a><a href="#guide-earnings">Matching fee<span>›</span></a>`:`<a href="#guides" data-action="my-proposals">Received proposals<span>${proposals().length?proposals().length+' · ':''}›</span></a>`}</div></section>`;}

function settingsPage(){return `<section class="settings-page">${window.ReelAccess.settings().replace(/<div class="account-setting-row">[\s\S]*?<\/a><\/div>/,()=>signupLanguageLink())}<section class="settings-group"><h2>Help & information</h2><a href="#support">Help and support<span>›</span></a><a href="#policies">Terms and privacy<span>›</span></a></section><section class="settings-group"><h2>Manage data</h2><button type="button" data-action="export-data">Download my data<span>↓</span></button><button type="button" data-action="reset" class="settings-danger">Delete saved data<span>›</span></button></section></section>`;}

function support(){return `<div class="centerbox">${title('Help','How can we help?','')}<div class="card pad"><h2 class="support-group-title">Common questions</h2><details><summary>Can I find a place without knowing its Korean name?</summary><p class="muted small">A public video link can suggest places. Some videos cannot be analyzed. If several branches share a name, compare their addresses.</p></details><details style="margin-top:16px"><summary>${guided?'Can my mate book a restaurant for me?':'Does saving a place reserve a table?'}</summary><p class="muted small">${guided?'Saving a place or requesting a mate does not reserve a table. Describe the help you need and check what is included in the final proposal.':'Saving places helps you plan visits. Restaurant bookings and ordering assistance are not included. Check reservation requirements with the venue.'}</p></details><details style="margin-top:16px"><summary>Why was a place not found?</summary><p class="muted small">Private videos, unclear names or multiple branches can make places hard to identify. Try a public link or add a place yourself.</p></details></div><form id="support-form" class="card pad" style="margin-top:20px"><h2 class="support-group-title">Write a message</h2><label>Topic<select name="type"><option>Place or video issue</option><option>Data or privacy request</option>${guided?'<option>Booking or refund</option>':''}<option>Other feedback</option></select></label><label style="margin-top:17px">How can we help?<textarea name="body" minlength="10" maxlength="1000" required placeholder="Which place or step do you need help with? Write in the language you are comfortable with. At least 10 characters."></textarea></label><button type="submit" class="btn" style="margin-top:18px">Save message</button></form>${state.tickets.length?`<div class="notice">${state.tickets.length} saved messages. Latest status: ${esc(statusLabel(state.tickets.at(-1).status))}. Not sent to support.</div>`:''}</div>`;}
function policies(){return `<article class="legalcopy">${title('Service information','Before you travel.','Place information와 Save 방식, 현금 지급·매칭 방식을 Information합니다.')}<h2>Places and maps</h2><p>Photos and maps help you explore. Check current hours, the correct branch and entrance before visiting. Map lines show visit order, not actual directions.</p><h2>Saving your trip</h2><p>Your trip is saved in this browser only. It does not sync automatically and may be lost if browser data is cleared. Download or delete it from My account.</p><h2>What is connected</h2><p>Video analysis, live directions and support messages are not connected yet.${guided?' Request a mate과 Message는 이 기기에만 Save됩니다. 실제 Mates 연락·Bookings·Matching fee 결제는 발생하지 않습니다. 여행 비용은 현장에서 Mates에게 현금으로 지급하는 구조입니다.':''}</p><h2>Privacy</h2><p>Do not enter real payment details or sensitive personal information. Shared itineraries do not include your contact details or conversations.</p><h2>Photos and content</h2><p>Open the original video using its link. Photos may not reflect how a place looks today.</p><div class="buttons"><a class="btn secondary" href="../docs/photo-credits.html">Photo credits</a>${btn('Help','support','secondary')}</div></article>`;}
function guides(){return `${title('','Mates')}<div class="trip-mode-tabs" role="group" aria-label="Mate menu"><button type="button" data-action="guides-tab" data-id="discover" aria-pressed="${guidesTab==='discover'}">${icon('guides')}<span>Find a travel mate</span></button><button type="button" data-action="guides-tab" data-id="requests" aria-pressed="${guidesTab==='requests'}">${icon('board')}<span>Received proposals</span>${proposals().length?`<span class="trip-request-count">${proposals().length}</span>`:''}</button></div><section class="trip-tab-panel">${guidesTab==='requests'?guideRequests():guideDiscovery()}</section>`;}
function guideDiscovery(){ensureDays();return `<div class="market-intro"><h2>Mate proposals for your trip</h2><p>Post your itinerary to receive plans and proposals from local mates.</p></div><section class="card pad"><span class="eyebrow">Trip to share</span><h2>${esc(state.title)}</h2><p>${state.days.length} ${state.days.length===1?"day":"days"} · ${state.board.length} ${state.board.length===1?"place":"places"} · ${esc(state.date)}</p>${mateNextButton('')}${btn('Edit my trip','planner','secondary')}</section>`;}

function journeySummary(q,priceLabel='Total for your group'){return `<section class="journey-summary"><div class="journey-guide"><span class="portrait">${esc(q.guide[0])}</span><div><h2>${esc(q.guide)}${q.guide==='Not matched yet'?'':' Mates'}</h2><p>English-speaking mate · Seongsu</p></div></div><div class="journey-facts"><div><span>Travel date</span><strong>${esc(q.date)}</strong></div><div><span>Start time · KST</span><strong>${esc(q.time)}</strong></div><div><span>Your group</span><strong>${q.party} ${q.party===1?"guest":"guests"}</strong></div><div><span>Getting around</span><strong>Mostly walking</strong></div></div>${q.amount!==undefined?`<div class="journey-price"><span>${priceLabel} · KRW</span><strong>${money(q.amount)}</strong><p>Total for ${q.party} ${q.party===1?"guest":"guests"}. Food, transport, shopping and entry fees are extra.</p></div>`:`<div class="journey-price pending"><span>Mate fee</span><strong>Price on request</strong><p>No payment now. Review your proposal before booking.</p></div>`}</section>`;}
function journeyPlan(plan){return `<ol class="journey-plan">${String(plan||'').split('\n').filter(line=>line.trim()).map((line,i)=>`<li><b>${i+1}</b><span>${esc(line.replace(/^\d+[.)]\s*/,''))}</span></li>`).join('')}</ol>`;}
function guidePage(){
 const mate=state.guide==='jun'?'jun':'mina';
 const photo=guide().photo;
 return `${title('','Meet your mate','')}
 <section class="mate-profile">
  <header class="mate-cover mate-cover--${mate}">
   <div class="mate-identity">
    ${photo?`<img class="mate-avatar" src="${esc(photo)}" alt="">`:''}
    <div><p class="mate-area">${signupText(mate+'Area')}</p><h2>${signupText(mate+'Title')}</h2></div>
   </div>
  </header>
  <div class="mate-bio">
   <p class="mate-intro">${signupText(mate+'Intro')}</p>
   <p class="mate-meta">${signupText('mateLanguages')}<br>${signupText('mateCapacity')}</p>
   <p class="mate-price-note">${signupText('matePriceNote')}</p>
  </div>
 </section>
 <section class="mate-help"><h2>How your mate can help</h2><ul>
  <li>${icon('guides')}<span>Explore the neighborhood in English</span></li>
  <li>${icon('cafe')}<span>Get help ordering in Korean at cafes and restaurants</span></li>
  <li>${icon('trips')}<span>Plan a practical visit order and find your way</span></li>
 </ul><p class="hint">Food, shopping, transport and entry fees are extra. Availability is checked after you request.</p></section><div class="bottomaction mate-request"><p>${signupText('mateNoPayment')}</p>${mateNextButton('')}</div>`;
}

function request(){if(state.booking&&!['cancelled'].includes(state.booking.status))return empty('You already have an active booking.','Bookings을 열거Me My account에서 앱을 초기화한 뒤 새 여정을 체험하세요.','booking','Open booking');if(state.request&&['requested','quoted'].includes(state.request.status))return empty('You already have an active request.','Check its status, or withdraw it before starting again.','requested','View request');const example=location.hash==='#request?sample=1';const day=example?sampleDay():{title:state.title,date:state.date,time:state.time,party:state.party,stops:requestStops().map(place)};if(!day.stops.length)return empty(signupText('pilotPlaces'),'', 'results',signupText('findEligible'));return `${steps(1)}${title('','Request a mate','')}<section class="handoff card pad"><span class="badge">${example?1:(state.day||0)+1} day only · No payment yet</span><h2 style="margin-top:14px">${esc(day.title)}</h2>${!example&&day.stops.length!==state.board.length?`<p>${signupText('onlySeongsu')}</p>`:''}<p>${day.date} · ${day.time} (Korea time · KST)</p><ol class="listclean">${day.stops.map(p=>`<li>${esc(p.name)} · ${p.duration} min</li>`).join('')}</ol>${example?'':btn('Edit this day','planner','secondary small')}</section><div class="split reverse"><form id="request-form" class="card pad"><h2>Your travel details</h2><div class="formrow"><label>Travel date<input type="date" name="date" required value="${day.date}"></label><label>Start time (KST)<input type="time" name="time" required value="${day.time}"></label></div><div class="formrow"><label>Guests<select name="party">${[1,2,3,4].map(n=>`<option value="${n}" ${day.party===n?'selected':''}>${n} ${n===1?"guest":"guests"}</option>`).join('')}</select></label><label>Tour language<select name="language"><option>English</option></select></label></div><div class="form-task-heading">What help do you need?</div><label>Anything your mate should know?<textarea name="notes" maxlength="500" placeholder="e.g. Please help us order in Korean. We prefer less walking. This cafe is a must-visit."></textarea></label><div class="form-task-heading">Before you send</div><label class="check"><input type="checkbox" name="guideAck" required>Share this itinerary and your requests with mates.</label><label class="check"><input type="checkbox" name="ack" required>I understand that sending a request does not confirm a booking.</label><p class="small muted">Please request at least 48 hours in advance. Guided days currently cover Seongsu and last up to 4 hours.</p><p id="request-error" class="error" role="alert"></p></form></div><div class="bottomaction journey-action"><p>No payment until you review your proposal</p><button type="submit" form="request-form" class="btn">${signupText('sendEstimate')}</button></div>`;}
function requested(){const r=state.request;if(!r)return empty('No mate requests yet.','My trips으로 Proposals을 받아보세요.','request','Find a travel mate');const list=proposals();return `${title('','Received proposals','Compare itineraries, inclusions and the total price.')}<section class="card pad request-summary-card"><span class="badge">${esc(statusLabel(r.status))}</span><h2>${esc(r.tripTitle||state.title)}</h2><p>${esc(r.date)} · ${r.party} ${r.party===1?"guest":"guests"} · ${(r.stops||[]).length} places</p>${state.booking||r.status==='booked'?btn('View booking','booking'):['requested','quoted'].includes(r.status)?action('Close request','withdraw','secondary small'):btn('Find a travel mate','request')}</section>${list.length?`<div class="proposal-section-heading"><h2>Mate proposals</h2><span>${list.length}</span></div><div class="proposal-grid">${list.map(q=>`<article class="card pad proposal-card"><div class="guide proposal-header"><span class="portrait">${esc(q.guide[0])}</span><div><h2>${esc(q.guide)}${q.guide==='Not matched yet'?'':' Mates'}</h2><p>English · Seongsu</p></div></div><p class="proposal-description">${esc(q.reason)}</p><strong class="proposal-price">${money(q.amount)}<small> / ${q.party} ${q.party===1?"guest":"guests"} All</small></strong><p class="hint proposal-validity">${q.expires>Date.now()?'Proposal available':'Expired'}</p>${action('View plan & proposal','select-proposal','secondary',`data-id="${esc(q.id)}"`)}</article>`).join('')}</div>`:`<div class="empty"><h2>Waiting for mate proposals</h2><p>Mates will review your trip and send their plans and proposals.</p></div>`}${!state.booking&&['requested','quoted'].includes(r.status)?`<details class="demo-next"><summary>View proposal</summary>${action('Compare sample proposals','demo-proposals','secondary')}</details>`:''}`;}

function quoteValid(){return state.quote&&state.quote.expires>Date.now()&&state.request?.status==='quoted';}
function quote(){const q=state.quote;if(!q)return empty('No proposal yet.','Your itinerary and proposal will appear here once your mate has reviewed your request.','requested','View request');const valid=quoteValid();return `${steps(2)}${title('Your mate proposal','Your itinerary and price.',`Proposals ${q.version} · ${state.booking?'Accepted proposal':valid?'Valid for 24 hours after issue':'Expired or withdrawn proposal'}`)}${journeySummary(q,'Cash payable in person')}<section class="card pad"><h2>Your proposed itinerary</h2>${journeyPlan(q.plan)}<details class="trip-settings"><summary><span>Compare with your request</span><b>view</b></summary>${journeyPlan((state.request?.stops||[]).map(p=>p.name+' · '+p.duration+' min').join('\n'))}</details><div class="notice"><strong>What changed and why</strong><p>${esc(q.reason)}</p></div></section><section class="card pad"><h2>Included in the price</h2>${taskGroup('Included',`<ul class="listclean"><li>${window.ReelRevenue.duration(q.pricing?.hours||4)}</li><li>Itinerary preparation and help getting around and ordering</li></ul>`,'visit')}${taskGroup('Not included','<p>Food, shopping, transport and entry fees</p><p class="hint">Venue reservations and skip-the-line access are not guaranteed.</p>','caution')}</section><details class="card pad journey-terms"><summary>Cash payment & cancellations</summary><p>Pay in cash in person. Discuss cancellations or return of cash already paid with your mate.</p></details><div class="bottomaction journey-action"><p>${state.booking?'Reviewed proposal':valid?'Total for your group · '+money(q.amount):'A new, valid proposal is needed'}</p>${state.booking?btn('View booked itinerary','booking'):valid?btn('Continue to booking','checkout'):btn(signupText('compareOffers'),'requested','secondary')}</div>`;}

function requestBooking(name,email){if(window.ReelAccess.isAdmin||window.ReelAccess.mode()!=='customer'||state.booking||!quoteValid())return false;const q=state.quote;state.booking={...JSON.parse(JSON.stringify(q)),id:'RT-DEMO-'+Date.now(),quoteVersion:q.version,status:'awaiting_mate_fee',customer:name,email,requestedAt:Date.now(),paymentMethod:'cash',feeRate:.1,feeAmount:Math.round(q.amount*.1),feeStatus:'pending',cashStatus:'uncollected',policyVersion:'CASH-MATCH-10-V1'};state.request.status='matching';state.request.guide=q.guide;state.request.guideId=q.guideId;save();return true;}
function confirmMateFee(outcome){const b=state.booking;if(window.ReelAccess.isAdmin||window.ReelAccess.mode()!=='guide'||!b||b.status!=='awaiting_mate_fee'||b.feeStatus==='paid')return false;if(outcome!=='success'){b.feeStatus='failed';save();return false;}b.feeStatus='paid';b.feePaidAt=Date.now();b.status='confirmed';b.confirmedAt=Date.now();state.request.status='booked';save();return true;}
function cashNotice(amount){return `<section class="card pad cash-notice"><span class="badge">Cash payment in person</span><h2>Bring cash on your trip day</h2><strong>${money(amount)}</strong><p>Pay your mate directly in cash. Reeltrip connects you and does not collect the trip fee.</p></section>`;}
function guideFee(){const b=state.booking;if(!b)return side('guide',empty('No booking has been selected.','You can pay the fee after a traveler selects you.','guide-desk','Requests'));return side('guide',`${title('','Confirm the match','The traveler selected your proposal.')}${journeySummary(b,'Cash to receive in person')}<section class="card pad"><h2>10% matching fee</h2><div class="summaryrow"><span>Agreed trip price</span><b>${money(b.amount)}</b></div><div class="summaryrow total"><span>Matching fee payable to Reeltrip</span><b>${money(b.feeAmount)}</b></div><p>Pay the matching fee to confirm the booking. Collect the trip price directly from the traveler in cash.</p>${b.status==='awaiting_mate_fee'?`<form id="mate-fee-form">${b.feeStatus==='failed'?`<p role="status">${signupText('feeRetry')}</p>`:''}<label class="check"><input type="checkbox" name="terms" required>I understand the 10% matching fee and direct cash payment.</label><label class="developer-only">Payment outcome<select name="outcome"><option value="success">Payment success</option><option value="failure">Payment failed</option></select></label><p id="mate-fee-error" class="error" role="alert"></p><button type="submit" class="btn">${money(b.feeAmount)} Pay and confirm booking</button></form>`:`<p>${b.feeStatus==='paid'?'Matching fee paid':'Payment is unavailable for the current status.'}</p>`}</section>`);}
function checkout(){if(state.booking)return empty('This proposal already has a booking request.','Open the booking to check its current status.','booking','Open booking');if(!quoteValid())return empty('You need a valid proposal.','Ask your mate for an updated itinerary and price.','quote','View proposal');const q=state.quote;return `${title('','Select mate & request booking','The booking is confirmed once your mate pays the matching fee.')}${journeySummary(q,'Cash payable in person')}${cashNotice(q.amount)}<form id="checkout-form" class="card pad"><h2>Traveler details</h2><label>Your name<input name="name" required maxlength="60" value="${esc(state.profile?.nickname||'')}" autocomplete="name"></label><label>Email<input name="email" type="email" required autocomplete="email"></label><label class="check"><input name="terms" type="checkbox" required>I agree to the itinerary and total price and will pay my mate in cash on the trip day.</label><label class="check"><input name="pendingAck" type="checkbox" required>I understand this is a booking request, confirmed only after the mate pays the matching fee.</label><p id="checkout-error" class="error" role="alert"></p><button type="submit" class="btn">Select mate & request booking</button></form>`;}

function booking(){const b=state.booking;if(!b)return empty('No bookings yet.','Mates의  days정과 가격을 확인한 뒤 Bookings을 요청하세요.','requested','View request');const pending=b.status==='awaiting_mate_fee',confirmed=['confirmed','completed'].includes(b.status);return `${title('Your guided trip',pending?'Waiting for your mate to confirm':statusLabel(b.status),b.id)}${pending?'<div class="notice">Your booking is pending until your mate pays the matching fee.</div>':''}${journeySummary(b,'Cash payable in person')}${cashNotice(b.amount)}${confirmed?`<section class="meeting-card"><span class="badge">Where to meet</span><h2>Seoul Forest Station, Exit 4</h2><p>${b.date} · ${b.time} / Korea time (KST)</p><p class="hint">Confirm the meeting exit with your mate.</p></section>`:''}<section class="card pad"><h2>${pending?'Requested itinerary':'Booked itinerary'}</h2>${journeyPlan(b.plan)}</section>${pending?btn(signupText('backTrips'),'trips','secondary small'):''}${['awaiting_mate_fee','confirmed'].includes(b.status)?`<section class="card pad">${btn(pending?'Withdraw booking request':'Cancel booking','cancel','secondary')}</section>`:''}${b.status==='cancellation_requested'?'<div class="notice">Your cancellation request is under review. Contact your mate about any cash already paid.</div>':''}${confirmed?`<div class="bottomaction journey-action">${b.status==='completed'&&!state.review?btn('Review your trip','review'):btn('Message your mate','chat')}</div>`:''}${state.review?`<section class="card pad"><h2>My review · ${state.review.rating}/5</h2><p>${esc(state.review.body)}</p></section>`:''}`;}

function chat(){if(!state.booking)return empty('Book a mate first.','Conversations are linked to a booking.','requested','View request');return `<div class="centerbox">${title('Talk to your mate',`${esc(state.booking.guide)} — your mate`,'')}<div class="card pad"><div class="chat" id="chat-log"><div class="bubble">Find your confirmed itinerary and meeting point in your booking details.<small>Information</small></div>${state.messages.map(m=>`<div class="bubble mine">${esc(m.text)}<small>Me</small></div>`).join('')}</div><form id="chat-form" style="display:flex;gap:10px"><input name="text" aria-label="Message" maxlength="1000" required placeholder="e.g. Which station exit should we use?" style="margin:0"><button type="submit" class="btn">Send</button></form></div></div>`;}
function refundEstimate(){return 0;}

function cancel(){const b=state.booking;if(!b||!['awaiting_mate_fee','confirmed'].includes(b.status))return empty('No booking is available to cancel.','Check your current booking status.','booking','View booking');return `${title('','Cancel your booking 요청')}<form id="cancel-form" class="card pad"><p>${b.status==='awaiting_mate_fee'?'Withdraw this unconfirmed booking request.':'Confirm any cash payments with your mate. Reeltrip does not collect or automatically refund trip payments.'}</p><label>Reason<textarea name="reason" required minlength="2" maxlength="500"></textarea></label><label class="check"><input name="terms" type="checkbox" required>I confirm this cancellation request.</label><button type="submit" class="btn danger">${b.status==='awaiting_mate_fee'?'Withdraw request':'Submit cancellation request'}</button></form>`;}

function review(){if(state.booking?.status!=='completed')return empty('Reviews open after your trip.','You can leave a review once the booking is marked completed.','booking','View booking');if(state.review)return empty('Your review is already saved.','Thank you for sharing your experience.','booking','View my review');return `<div class="centerbox">${title('Share your experience','How was your trip?','')}<form id="review-form" class="card pad"><label>Overall rating</label><div class="rating">${[1,2,3,4,5].map(n=>`<button type="button" class="${state.rating>=n?'selected':''}" data-action="rate" data-value="${n}" aria-label="Out of 5: ${n} stars" aria-pressed="${state.rating===n}">★</button>`).join('')}</div><label>My review<textarea name="body" required minlength="10" maxlength="1000" placeholder="What went well? Was the tour as described? Share anything other travelers should know."></textarea></label><p id="review-error" class="error" role="alert"></p><button type="submit" class="btn" style="margin-top:20px">Save review</button></form></div>`;}
function side(role,content){if(role==='guide')return content;const list=screens.filter(s=>s.role===role);return `<div class="adminlayout"><nav class="sidenav" aria-label="Role navigation">${list.map(s=>`<a class="${current()===s.route?'active':''}" href="#${s.route}">${s.name}</a>`).join('')}</nav><section>${content}</section></div>`;}
function guideDesk(){const r=state.request;return side('guide',`${state.booking?.status==='awaiting_mate_fee'?`<section class="card pad"><span class="badge">The traveler selected you</span><h2>Pay the matching fee to confirm</h2><p>${money(state.booking.feeAmount)} · 10% of the trip price</p>${btn('Pay fee & confirm','guide-fee')}</section>`:state.booking?.feeStatus==='paid'?btn(signupText('feeReceipt'),'guide-earnings','secondary small'):''}${title('','Open trips','Review the trip and send your own itinerary and proposal.')}${!r?empty('No new requests.','Keep your availability up to date.','guide-calendar','Manage availability'):`<div class="card pad"><span class="badge">${r.id} · ${statusLabel(r.status)}</span><h2 style="margin:15px 0">${r.date} · ${r.party} ${r.party===1?"guest":"guests"} · ${r.time}</h2><p>${r.stops.map(p=>esc(p.name)).join(' → ')}</p><div class="notice">Traveler notes: ${esc(r.notes||'No additional requests')}<br>Must-visits: ${r.must.map(id=>r.stops.find(p=>p.id===id)?.name||id).map(esc).join(', ')||'None'}</div><div class="buttons">${r.status==='requested'||r.status==='quoted'?`${btn('Review itinerary and proposal','guide-quote')}`:''}</div></div>`}<details class="trip-settings"><summary><span>Work summary</span><b>＋</b></summary><div class="metrics"><div class="metric">Awaiting reply<strong>${r?.status==='requested'?1:0}</strong></div><div class="metric">Proposals issued<strong>${state.quote?1:0}</strong></div><div class="metric">Bookings<strong>${state.booking?1:0}</strong></div></div></details>`);}
function guideQuote(){const r=state.request;if(!r||!['requested','quoted'].includes(r.status)||state.booking)return side('guide',empty('No request available to proposal.','Check its status in your inbox.','guide-desk','Requests'));return side('guide',`${title('Edit proposal','Shape the traveler’s day','The published itinerary and price appear in the traveler proposal.')}<form id="quote-form" class="card pad"><label class="developer-only">Sending account<select name="sender"><option value="mina">Mina</option><option value="jun">Jun</option></select></label>${window.ReelRevenue.calculator(state.request.party)}<label>Final itinerary (shown to the traveler)<textarea name="plan" required minlength="10" maxlength="2000">${esc(state.quote?.plan||r.stops.map((p,i)=>`${i+1}. ${p.name} · ${p.duration} min`).join('\n'))}</textarea></label><label style="margin-top:18px">Changes and reasons (shown to the traveler)<textarea name="reason" required minlength="5" maxlength="500">${esc(state.quote?.reason||'The selected places are unchanged. Travel and rest times need final confirmation.')}</textarea></label><div class="formrow"><label>Total group price (KRW)<input type="number" name="amount" min="100000" max="1000000" step="500" readonly required value="${state.quote?.amount||window.ReelRevenue.quoteAmount(state.request.party)}"></label><label>Proposal validity<input value="24 hours after issue · Proposed policy" disabled></label></div><div class="notice">포함: English mate for the selected duration and itinerary preparation / 불포함: 식비·Shopping·교통·입장료. Updating your proposal keeps other mates’ proposals unchanged.</div><p id="quote-error" class="error" role="alert"></p><button class="btn" type="submit">Send a trip proposal</button></form>`);}
function guideCalendar(){return side('guide',`${title('Availability','Manage availability','')}<div class="card pad"><h2>${state.request?.date||state.date}</h2><p class="muted" style="margin:15px 0">Accepting new requests: <strong>${state.available?'Available':'Unavailable'}</strong></p>${action(state.available?'Mark this date unavailable':'Mark this date available','availability','secondary')}<div class="notice">This setting does not cancel confirmed bookings. Contact operations if a change is needed.</div></div>`);}
function earnings(){const b=state.booking;return side('guide',`${title('','Matching fee','Collect the trip price directly from the traveler in cash.')}<section class="card pad"><div class="summaryrow"><span>Agreed cash amount</span><b>${money(b?.amount||0)}</b></div><div class="summaryrow"><span>10% matching fee</span><b>${money(b?.feeAmount||0)}</b></div><div class="summaryrow"><span>Matching fee payment status</span><b>${!b?'No booking':b.feeStatus==='paid'?'Paid':b.feeStatus==='failed'?'Payment failed':'Pending payment'}</b></div><p>The platform does not settle or transfer trip payments. Confirm cash receipt directly with the traveler.</p>${b?.status==='awaiting_mate_fee'?btn('Pay fee & confirm','guide-fee'):''}</section>`);}

function admin(){return side('admin',`${title('Operations','Operations overview','These figures reflect local browser data, not real business activity.')}<div class="metrics"><div class="metric">Saved places<strong>${state.board.length}</strong></div><div class="metric">Needs checking<strong>${state.places.filter(p=>!p.verified).length}</strong></div><div class="metric">${guided?'Bookings':'Support'}<strong>${guided?(state.booking?1:0):state.tickets.length}</strong></div></div><div class="card pad"><h2>Needs your attention</h2><ul class="listclean"><li><a href="#admin-places">Review places and locations →</a></li><li><a href="#admin-support">Support tickets: ${state.tickets.filter(t=>t.status==='open').length} →</a></li>${guided?`<li><a href="#admin-guides">Jun’s mate application: ${statusLabel(state.adminReview)} →</a></li><li><a href="#admin-bookings">Check bookings and refunds →</a></li>`:''}</ul></div>`);}
function adminPlaces(){return side('admin',`${title('Place quality','Review places','Review original place data and correction history.')}<div class="tablewrap"><table><thead><tr><th>Place</th><th>Status</th><th>Review action</th></tr></thead><tbody>${state.places.map(p=>`<tr><td><b>${esc(p.name)}</b><br>${esc(p.address)}</td><td><span class="badge ${p.verified?'':'warm'}">${p.verified?'Successful':p.rejected?'Rejected':'Needs checking'}</span></td><td><button class="textbtn" data-action="correct" data-id="${p.id}">Review and edit</button>${!p.verified?`<br><button class="textbtn" data-action="reject-place" data-id="${p.id}">Rejected</button>`:''}</td></tr>`).join('')}</tbody></table></div>`);}
function adminSupport(){return side('admin',`${title('Support tickets:','Support and data requests','Requests and status updates stay in this browser. Nothing is sent externally.')}<div class="stack">${state.tickets.length?state.tickets.map(t=>`<div class="card pad"><span class="badge">${t.id} · ${statusLabel(t.status)}</span><h3 style="margin:13px 0">${esc(t.type)}</h3><p>${esc(t.body)}</p>${t.status==='open'?`<button class="btn secondary small" style="margin-top:15px" data-action="resolve-ticket" data-id="${t.id}">Mark resolved</button>`:''}</div>`).join(''):empty('No support requests yet.','Create a local request from the help screen.','support','Open support')}</div>`);}
function adminGuides(){return side('admin',`${title('Mate verification','Review mate credentials','Fictional applicant Jun · No real credentials or identity documents are collected.')}<form id="verify-form" class="card pad"><div class="guide"><div class="portrait">Jun</div><div><h2>Jun · Anguk</h2><span class="badge">${statusLabel(state.adminReview)}</span></div></div><div class="notice">In a live service, staff must verify credentials, identity and contracts. Sensitive evidence must not appear on public profiles.</div>${['Check tourist interpreter qualification and language','Check that the identity matches the evidence','Check mate contract and payout agreement'].map((t,i)=>`<label class="check"><input name="v${i}" type="checkbox" required>${t} (review only)</label>`).join('')}<div class="buttons"><button type="submit" class="btn">Approve and publish profile</button>${action('Request information and hide profile','guide-needs-info','secondary')}</div></form>`);}
function adminBookings(){const b=state.booking;return side('admin',`${title('','Matching & booking management')}${!b?'<p>No bookings.</p>':`<section class="card pad"><h2>${esc(b.guide)} · ${esc(b.date)}</h2><span class="badge">${statusLabel(b.status)}</span><div class="summaryrow"><span>Agreed cash amount</span><b>${money(b.amount)}</b></div><div class="summaryrow"><span>10% matching fee</span><b>${money(b.feeAmount)}</b></div><p>Matching fee status: ${esc(b.feeStatus)}</p><p>Cancellation reason: ${esc(b.cancelReason||'—')}</p><p>Trip payments are direct cash transactions. Matching fee refunds require separate review.</p>${b.status==='cancellation_requested'?action('Confirm cancellation','confirm-cash-cancel','secondary'):''}</section>`}`);}

